// ── Social Links Component ────────────────────────────────────────────────────

function SocialLinks({ socials }: { socials: typeof channels[0]["socials"] }) {
  const links = [
    { href: socials.facebook, icon: <FacebookIcon />, label: "Facebook" },
    { href: socials.instagram, icon: <InstagramIcon />, label: "Instagram" },
    { href: socials.youtube, icon: <YouTubeIcon />, label: "YouTube" },
    { href: socials.linkedin, icon: <LinkedInIcon />, label: "LinkedIn" },
  ];

  return (
    <div className="relative z-10 flex gap-3 mt-3">
      {links.map(({ href, icon, label }) => (
        <a
          key={label}
          href={href}
          target="_blank"
          rel="noopener noreferrer"
          aria-label={label}
          onClick={(e) => e.stopPropagation()}
          className="flex items-center justify-center w-8 h-8 rounded-full border border-white/10 bg-white/5 text-white/40 hover:text-emerald-400 hover:border-emerald-500/50 hover:bg-emerald-500/10 hover:shadow-[0_0_12px_rgba(16,185,129,0.3)] transition-all duration-300"
        >
          {icon}
        </a>
      ))}
    </div>
  );
}

