"use client";

import Image from "next/image";
import { ArrowRight, Play } from "lucide-react";
import { motion } from "framer-motion";

export default function Hero() {
  return (
    <section className="relative min-h-screen overflow-hidden bg-background">
        <div className="absolute left-0 top-0 h-[800px] w-[800px] rounded-full blur-[180px]" />
      <div className="grid min-h-screen lg:grid-cols-[45%_55%]">
        {/* LEFT */}
        <div className="relative z-20 flex flex-col justify-center px-6 pt-32 pb-20 md:px-10 lg:px-16">
          <motion.div
            initial={{ opacity: 0, y: 25 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7 }}
            className="mb-8 flex items-center gap-4"
          >
            <div className="h-px w-10 bg-accent-green" />
            <span className="text-xs uppercase tracking-[0.35em] text-accent-green">
              Pakistan's Modern Media Network
            </span>
          </motion.div>

          <motion.h1
            initial={{ opacity: 0, y: 25 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.15, duration: 0.8 }}
            className="font-heading uppercase leading-[0.78]"
          >
            <span className="block text-5xl text-white md:text-6xl">
              Welcome To
            </span>

            <span className="block text-[5rem] text-white md:text-[7rem] xl:text-[11rem]">
              House Of
            </span>

            <span className="block text-[5rem] text-accent-green md:text-[7rem] xl:text-[11rem]">
              Wasila
            </span>
          </motion.h1>

          <motion.p
            initial={{ opacity: 0, y: 25 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="mt-8 border-l-2 border-accent-green pl-4 text-xs uppercase tracking-[0.25em] text-muted-text"
          >
            One Network · Seven Channels · Infinite Stories
          </motion.p>

          <motion.p
            initial={{ opacity: 0, y: 25 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.45 }}
            className="mt-8 max-w-xl text-base leading-8 text-muted-text"
          >
            A unified media empire built for the digital era. We produce,
            broadcast, and distribute premium content across news, sports,
            entertainment, faith, and culture — reaching audiences across
            Pakistan and beyond.
          </motion.p>

          <motion.div
  initial={{ opacity: 0, y: 25 }}
  animate={{ opacity: 1, y: 0 }}
  transition={{ delay: 0.6 }}
  className="mt-12 flex flex-col gap-4 sm:flex-row"
>
    <a href="#channels">
  <button className="group inline-flex h-16 items-center justify-center gap-3 rounded-full bg-accent-green px-10 text-sm font-semibold uppercase tracking-[0.25em] text-black transition-all duration-300 hover:scale-[1.03] hover:shadow-[0_0_40px_rgba(0,217,95,0.35)]">
    Explore Channels
    <ArrowRight
      size={18}
      className="transition-transform duration-300 group-hover:translate-x-1"
    />
  </button>
  </a>

  <a href="#reels">
  <button className="group inline-flex h-16 items-center justify-center gap-4 rounded-full border border-white/15 bg-white/[0.03] px-10 text-sm uppercase tracking-[0.22em] text-white backdrop-blur-sm transition-all duration-300 hover:border-white/30 hover:bg-white/[0.06]">
  
    <div className="flex h-10 w-10 items-center justify-center rounded-full bg-white/10">
      <Play size={16} />
    </div>

    Watch Showreel
  </button>
  </a>
</motion.div>
        </div>

        {/* RIGHT */}
        
        <div className="relative hidden lg:flex lg:min-h-screen items-center justify-center">
          <Image
            src="/welcome-hero.png"
            alt="House Of Wasila Media Network"
            fill
            priority
            className="max-h-[95vh] w-auto object-contain"
          />

         

          <div className="glass absolute right-6 top-8 z-20 flex items-center gap-3 px-4 py-2">
           
        
          </div>
          <div className="absolute bottom-12 right-10 z-30 hidden lg:flex items-start gap-12">
  <div>
    <div className="font-heading text-6xl leading-none text-accent-green">
      7+
    </div>

    <p className="mt-2 text-xs uppercase tracking-[0.22em] text-white/70">
      Independent
      <br />
      Channels
    </p>
  </div>

  <div className="border-l border-white/10 pl-12">
    <div className="font-heading text-6xl leading-none text-accent-green">
      100%
    </div>

    <p className="mt-2 text-xs uppercase tracking-[0.22em] text-white/70">
      Digital
      <br />
      First
    </p>
  </div>

  <div className="border-l border-white/10 pl-12">
    <div className="font-heading text-6xl leading-none text-accent-green">
      Global
    </div>

    <p className="mt-2 text-xs uppercase tracking-[0.22em] text-white/70">
      Audience
      <br />
      Reach
    </p>
  </div>
</div>
        </div>
      </div>

      <div className="absolute bottom-8 left-1/2 z-30 -translate-x-1/2">
        <div className="flex flex-col items-center gap-3">
          <span className="text-[10px] uppercase tracking-[0.35em] text-muted-text">
            Scroll To Explore
          </span>

          <div className="h-10 w-px bg-gradient-to-b from-accent-green to-transparent" />
        </div>
      </div>
    </section>
  );
}

function Stat({
  number,
  label,
}: {
  number: string;
  label: string;
}) {
  return (
    <div>
      <div className="font-heading text-4xl text-accent-green">
        {number}
      </div>

      <div className="mt-1 text-[10px] uppercase tracking-[0.25em] text-muted-text">
        {label}
      </div>
    </div>
  );
}